class LoginBloc:
    def __init__(self) -> None:
        self.state = State()                 # immutable snapshot
        self.events: asyncio.Queue[Event] = asyncio.Queue()
        self._subs: list[Callable[[State], None]] = []
    async def run(self) -> None:
        while True:
            ev = await self.events.get()     # sequential by construction
            self.state = reduce(self.state, ev)   # pure reducer
            for notify in list(self._subs): notify(self.state)
    def dispatch(self, ev: Event) -> None:
        self.events.put_nowait(ev)           # cross-thread: call_soon_threadsafe
